function subarraysDivByK(nums, k) {
  const seen = new Map([[0, 1]]);                    // remainder -> times seen so far
  let sum = 0, count = 0;
  for (const x of nums) {
    sum += x;
    const r = ((sum % k) + k) % k;                    // 0..k-1, even when sum is negative
    count += seen.get(r) ?? 0;                        // same remainder: the gap is a multiple of k
    seen.set(r, (seen.get(r) ?? 0) + 1);
  }
  return count;
}

int subarraysDivByK(int[] nums, int k) {
    Map<Integer, Integer> seen = new HashMap<>();       // remainder -> times seen so far
    seen.put(0, 1);
    int sum = 0, count = 0;
    for (int x : nums) {
        sum += x;
        int r = ((sum % k) + k) % k;                     // 0..k-1, even when sum is negative
        count += seen.getOrDefault(r, 0);                // same remainder: the gap is a multiple of k
        seen.merge(r, 1, Integer::sum);
    }
    return count;
}

int subarraysDivByK(vector<int>& nums, int k) {
    unordered_map<int, int> seen{{0, 1}};              // remainder -> times seen so far
    int sum = 0, count = 0;
    for (int x : nums) {
        sum += x;
        int r = ((sum % k) + k) % k;                    // 0..k-1, even when sum is negative
        count += seen[r];                               // same remainder: the gap is a multiple of k
        seen[r]++;
    }
    return count;
}

function subarraysDivByK(nums, k) {
  const seen = new Array(k).fill(0);                 // remainder -> times seen: keys are 0..k-1
  seen[0] = 1;
  let rem = 0, count = 0;
  for (const x of nums) {
    rem = (((rem + x) % k) + k) % k;                  // keep only the remainder
    count += seen[rem];
    seen[rem]++;
  }
  return count;
}

